template-columns:1fr 80px 90px 90px;padding:10px 4px;font-size:13px;border-bottom:1px solid rgba(255,255,255,.05);align-items:center}.mt-head{font-size:11px;color:rgba(255,255,255,.25)}.mt-clickable{cursor:pointer}.mt-clickable:hover{background:rgba(255,255,255,.04)}.mt-active{background:rgba(123,127,178,.12)}.mt-dimmed{opacity:.35}.mt-model{color:rgba(255,255,255,.8)}.mt-model em{display:block;font-style:normal;font-size:11px;color:rgba(255,255,255,.28);margin-top:2px}.mt-row span:not(:first-child){text-align:right;color:rgba(255,255,255,.55)}.model-filter-tag{display:inline-flex;padding:3px 10px;border-radius:6px;background:rgba(123,127,178,.18);font-size:12px;color:rgba(169,164,216,.9)}@media(max-width:720px){.usage-summary{grid-template-columns:1fr}.mt-row{grid-template-columns:1fr 55px 65px 65px}}
</style>
